-- AT-203 (provisional number 0045; renumber at merge): the blessing fund.
-- Spec: docs/FAVO_PRD_v7.md §6.10, §10.3 (donor_funds, donor_fund_entries,
-- donor_fund_members, payments.fund_topup_id), §10.6, L44–L47, REQ-160…177.
-- Generated by drizzle-kit from db/schema.ts + db/enums.ts, then hand-edited:
-- the append-only triggers at the end (§10.6: "Never DELETE or UPDATE rows in
-- … donor_fund_entries"), written like audit_log's (0021, 0025).
--
--   donor_funds         the fund. NO balance column — the ledger is the truth.
--   donor_fund_entries  the append-only ledger, signed integer cents. A card
--                       top_up counts toward the balance only while its
--                       payment is `successful` (§6.10.3); cash/EFT carry a
--                       reference (L44, REQ-161).
--   donor_fund_members  the linked names. (fund_id, fund_active) is a foreign
--                       key to donor_funds(id, active) ON UPDATE CASCADE, so the
--                       partial unique index "one active fund per customer"
--                       (L46, REQ-172) can be enforced by the database.
--   payments            fund_topup_id gets its FK to donor_fund_entries, and
--                       (fund_topup_id, attempt) is UNIQUE like (order_id,
--                       attempt). The exactly-one-subject CHECK and the
--                       one-successful-per-top-up index are already in 0035.
--
-- orders.payment_mode is a text column (no DB enum), so `donor_fund` needs no
-- DDL here. The reverse is drizzle/down/0045_at203_blessing_fund.down.sql.

CREATE TYPE "public"."donor_fund_entry_kind" AS ENUM('top_up', 'spend', 'sweep', 'adjustment');--> statement-breakpoint
CREATE TYPE "public"."funding_method" AS ENUM('card', 'cash', 'eft');--> statement-breakpoint
CREATE TABLE "donor_fund_entries" (
	"id" text PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" text DEFAULT 'hofmi' NOT NULL,
	"fund_id" text NOT NULL,
	"kind" "donor_fund_entry_kind" NOT NULL,
	"amount_zar" integer NOT NULL,
	"order_id" text,
	"payment_id" text,
	"funding_method" "funding_method",
	"reference" text,
	"client_uuid" text,
	"recorded_by_staff_id" text NOT NULL,
	"reason" text,
	"at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "donor_fund_entries_client_uuid_unique" UNIQUE("client_uuid"),
	CONSTRAINT "donor_fund_entries_sign" CHECK (("donor_fund_entries"."kind" = 'top_up' AND "donor_fund_entries"."amount_zar" > 0) OR ("donor_fund_entries"."kind" IN ('spend', 'sweep') AND "donor_fund_entries"."amount_zar" < 0) OR ("donor_fund_entries"."kind" = 'adjustment' AND "donor_fund_entries"."amount_zar" > 0)),
	CONSTRAINT "donor_fund_entries_adjustment_order" CHECK ("donor_fund_entries"."kind" <> 'adjustment' OR "donor_fund_entries"."order_id" IS NOT NULL),
	CONSTRAINT "donor_fund_entries_method" CHECK (("donor_fund_entries"."kind" = 'top_up') = ("donor_fund_entries"."funding_method" IS NOT NULL)),
	CONSTRAINT "donor_fund_entries_card_uuid" CHECK (("donor_fund_entries"."kind" = 'top_up' AND "donor_fund_entries"."funding_method" = 'card') = ("donor_fund_entries"."client_uuid" IS NOT NULL)),
	CONSTRAINT "donor_fund_entries_offline_reference" CHECK ("donor_fund_entries"."funding_method" IS NULL OR "donor_fund_entries"."funding_method" = 'card' OR length(btrim(coalesce("donor_fund_entries"."reference", ''))) > 0),
	CONSTRAINT "donor_fund_entries_spend_order" CHECK ("donor_fund_entries"."kind" <> 'spend' OR "donor_fund_entries"."order_id" IS NOT NULL),
	CONSTRAINT "donor_fund_entries_sweep_reason" CHECK ("donor_fund_entries"."kind" <> 'sweep' OR length(btrim(coalesce("donor_fund_entries"."reason", ''))) > 0)
);
--> statement-breakpoint
CREATE TABLE "donor_fund_members" (
	"fund_id" text NOT NULL,
	"customer_id" text NOT NULL,
	"fund_active" boolean DEFAULT true NOT NULL,
	"added_by_staff_id" text NOT NULL,
	"at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "donor_fund_members_pkey" PRIMARY KEY("fund_id","customer_id")
);
--> statement-breakpoint
CREATE TABLE "donor_funds" (
	"id" text PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" text DEFAULT 'hofmi' NOT NULL,
	"code" text NOT NULL,
	"display_name" text,
	"donor_customer_id" text,
	"non_refundable_ack_by" text NOT NULL,
	"active" boolean DEFAULT true NOT NULL,
	"created_by_staff_id" text NOT NULL,
	"at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "donor_funds_code_unique" UNIQUE("code"),
	CONSTRAINT "donor_funds_id_active_unique" UNIQUE("id","active"),
	CONSTRAINT "donor_funds_code_shape" CHECK ("donor_funds"."code" ~ '^FVO-[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{4}$')
);
