CREATE FUNCTION "donor_fund_entries_append_only"() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'donor_fund_entries is append-only: % is not allowed — void with a compensating entry', TG_OP;
END;
$$ LANGUAGE plpgsql;--> statement-breakpoint
